import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 수수료 금액의 현행 산출식을 알 수 없어 적용 단가(unit_price)를 그대로 수수료 금액으로 쓴다.
// 가정: 등록 직후 마감 상태는 '신청'이다.
const INITIAL_CLOSING_STATUS = '신청';
const FEE_TYPES = ['심사', '재발급'];
const REGISTRATION_TYPES = ['일반', '오프라인'];

function invalid(message: string): ApiError {
  return new ApiError(422, 'FEE_RECORD_INVALID', message);
}

function optionalText(value: unknown, max: number, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  if (value.length > max) {
    throw invalid(label + '은(는) ' + max + '자 이하여야 합니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr04202Controller {
  @Post('/fee-records')
  @HttpCode(200)
  async createFeeRecord(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);

    const feeType = data['feeType'];
    if (typeof feeType !== 'string' || !FEE_TYPES.includes(feeType)) {
      throw invalid('수수료 구분은 심사 또는 재발급이어야 합니다.');
    }
    const registrationType = optionalText(data['registrationType'], 255, '등록 구분');
    if (registrationType !== null && !REGISTRATION_TYPES.includes(registrationType)) {
      throw invalid('등록 구분은 일반 또는 오프라인이어야 합니다.');
    }
    const caseNo = optionalText(data['caseNo'], 50, '건 번호');
    const caseName = optionalText(data['caseName'], 200, '건명');
    const registeredOn = data['registeredOn'];
    if (typeof registeredOn !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(registeredOn)) {
      throw invalid('등록일자는 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const rawResolution = data['expenseResolutionId'];
    let expenseResolutionId: number | null = null;
    if (rawResolution !== undefined && rawResolution !== null && rawResolution !== '') {
      if (typeof rawResolution !== 'number' || !Number.isInteger(rawResolution)) {
        throw invalid('결의서 형식이 올바르지 않습니다.');
      }
      expenseResolutionId = rawResolution;
    }

    return transaction(async (db) => {
      if (expenseResolutionId !== null) {
        const found = await db.query(
          `SELECT expense_resolution_id FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint)`,
          { id: expenseResolutionId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '결의서를 찾을 수 없습니다.');
        }
      }

      const prices = await db.query(
        `SELECT fee_unit_price_id AS "feeUnitPriceId"
           FROM fee_unit_price
          WHERE fee_type = :feeType
            AND use_yn = '사용'
            AND (effective_from IS NULL OR effective_from <= CAST(:registeredOn AS date))
            AND (effective_to IS NULL OR effective_to >= CAST(:registeredOn AS date))
          ORDER BY effective_from DESC NULLS LAST, fee_unit_price_id DESC
          LIMIT 1`,
        { feeType, registeredOn },
      );
      if (prices.length === 0) {
        throw new ApiError(422, 'FEE_UNIT_PRICE_NOT_REGISTERED', '적용할 수수료 단가가 등록되어 있지 않습니다.');
      }
      const feeUnitPriceId = prices[0]['feeUnitPriceId'];

      const rows = await db.query(
        `INSERT INTO fee_record (
           fee_unit_price_id, expense_resolution_id, fee_type, registration_type,
           case_no, case_name, registered_on, fee_amount, closing_status,
           created_at, updated_at
         )
         VALUES (
           CAST(:feeUnitPriceId AS bigint),
           CAST(:expenseResolutionId AS bigint),
           :feeType,
           :registrationType,
           :caseNo,
           :caseName,
           CAST(:registeredOn AS date),
           (SELECT unit_price FROM fee_unit_price WHERE fee_unit_price_id = CAST(:feeUnitPriceId AS bigint)),
           :closingStatus,
           now(),
           now()
         )
         RETURNING fee_record_id AS "feeRecordId", fee_amount AS "feeAmount"`,
        {
          feeUnitPriceId,
          expenseResolutionId,
          feeType,
          registrationType,
          caseNo,
          caseName,
          registeredOn,
          closingStatus: INITIAL_CLOSING_STATUS,
        },
      );
      return rows[0];
    });
  }
}

