import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr04202Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [feeType, setFeeType] = useState('');
  const [registrationType, setRegistrationType] = useState('');
  const [caseNo, setCaseNo] = useState('');
  const [caseName, setCaseName] = useState('');
  const [registeredOn, setRegisteredOn] = useState('');
  const [expenseResolutionId, setExpenseResolutionId] = useState<number | string>('');

  const total = results.reduce((sum, row) => sum + Number(row['feeAmount'] ?? 0), 0);

  function openDrawer() {
    setFeeType('');
    setRegistrationType('');
    setCaseNo('');
    setCaseName('');
    setRegisteredOn('');
    setExpenseResolutionId('');
    setOpen(true);
  }

  async function submit() {
    if (!feeType) {
      throw new Error('수수료 구분을 선택해 주세요.');
    }
    if (!registeredOn) {
      throw new Error('등록일자를 입력해 주세요.');
    }
    const body: Row = {
      feeType,
      registrationType,
      caseNo,
      caseName,
      registeredOn,
      expenseResolutionId,
    };
    const res = await call<Row>('POST', '/fee-records', role, body);
    setResults([
      {
        ...body,
        feeRecordId: res['feeRecordId'],
        feeAmount: res['feeAmount'],
        closingStatus: '신청',
      },
      ...results,
    ]);
    setOpen(false);
    notify('심사수수료를 등록했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-6">
        <h2>이번 등록 건수</h2>
        <Tiles items={[['등록 건수', <Num value={results.length} />]]} />
      </section>
      <section className="box span-6">
        <h2>수수료 합계</h2>
        <Tiles items={[['수수료 금액 합계', <Num value={total} />]]} />
      </section>
      <section className="box span-12">
        <h2>등록 내역</h2>
        <Band total={results.length}>
          <button type="button" onClick={openDrawer}>수수료 등록</button>
        </Band>
        <DataTable
          rows={results}
          empty="이 화면에서 등록한 내역이 없습니다."
          columns={[
            { key: 'feeRecordId', label: '수수료 내역 ID' },
            { key: 'feeType', label: '수수료 구분' },
            { key: 'registrationType', label: '등록 구분' },
            { key: 'caseNo', label: '건 번호' },
            { key: 'caseName', label: '건명' },
            { key: 'registeredOn', label: '등록일자', render: (r) => <DateText value={r['registeredOn']} /> },
            {
              key: 'expenseResolutionId',
              label: '결의서',
              render: (r) => <RefName table="expense_resolution" role={role} value={r['expenseResolutionId']} />,
            },
            { key: 'feeAmount', label: '수수료 금액', render: (r) => <Num value={r['feeAmount']} /> },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r['closingStatus']} /> },
          ]}
        />
      </section>
      {open && (
        <Drawer title="수수료 등록" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="등록">
            <Field label="수수료 구분" required>
              <Select
                value={feeType}
                onChange={setFeeType}
                options={[['심사', '심사'], ['재발급', '재발급']]}
              />
            </Field>
            <Field label="등록 구분">
              <Select
                value={registrationType}
                onChange={setRegistrationType}
                options={[['일반', '일반'], ['오프라인', '오프라인']]}
              />
            </Field>
            <Field label="건 번호">
              <TextInput value={caseNo} onChange={setCaseNo} />
            </Field>
            <Field label="건명">
              <TextInput value={caseName} onChange={setCaseName} />
            </Field>
            <Field label="등록일자" required>
              <DateInput value={registeredOn} onChange={setRegisteredOn} />
            </Field>
            <Field label="결의서">
              <LookupSelect
                table="expense_resolution"
                role={role}
                value={expenseResolutionId}
                onChange={setExpenseResolutionId}
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
